ERLIN PAOLA LOPEZ VAZQUEZ", "guia": "A231265", "cliente": "MERLIN PAOLA LOPEZ VAZQUEZ", "rfc": "LOVM900722BD8", "agente": "Benjamin Farrera Rodriguez", "vta": "VTA53", "entidad": "MÉXICO CALLE DOS", "ciudad": "TAPACHULA", "estado": "CHIAPAS", "transportista": "MEXICANA DE FLETE", "transporte": "Transportista", "fpedido": "2026-06-01", "fembarque": "2026-06-05", "eest": "2026-06-12", "ereal": null, "estatus": "Backorder", "flete": 39333.12, "nfact": 6, "facturas": [{"factura": "CA2VF0020912", "ffactura": "2026-06-04", "estatus": "Backorder", "temporada": "Toda ocasión", "pedido": "CA2VP0021936", "fpedido": "2026-06-01"}, {"factura": "CA2VF0020913", "ffactura": "2026-06-04", "estatus": "Backorder", "temporada": "Toda ocasión", "pedido": "CA2VP0021937", "fpedido": "2026-06-01"}, {"factura": "CA2VF0020914", "ffactura": "2026-06-04", "estatus": "Surtido", "temporada": "Toda ocasión", "pedido": "CA2VP0021938", "fpedido": "2026-06-01"}, {"factura": "CA2VF0020915", "ffactura": "2026-06-04", "estatus": "Backorder", "temporada": "Caja blanca", "pedido": "CA2VP0021939", "fpedido": "2026-06-01"}, {"factura": "CA2VF0020916", "ffactura": "2026-06-04", "estatus": "Backorder", "temporada": "Toda ocasión", "pedido": "CA2VP0021940", "fpedido": "2026-06-01"}, {"factura": "CA2VF0020900", "ffactura": "2026-06-04", "estatus": "Backorder", "temporada": "Toda ocasión", "pedido": "CA2VP0021976", "fpedido": "2026-06-02"}]}], "logo": "data:image/jpeg;base64,"};</script>
<script>(function(){'use strict';
const D=window.__DATA__;
const $=s=>document.querySelector(s);
const el=(t,c,h)=>{const e=document.createElement(t);if(c)e.className=c;if(h!=null)e.innerHTML=h;return e;};
const today=new Date(D.generado+'T00:00:00');
const parseD=s=>s?new Date(s+'T00:00:00'):null;
const daysBetween=(a,b)=>Math.round((b-a)/86400000);
const fmtDate=s=>{if(!s)return '—';const d=parseD(s);return d.toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'});};

function progress(g){
  const emb=parseD(g.fembarque),est=parseD(g.eest),real=parseD(g.ereal);
  if(/cancel/i.test(g.estatus||'')) return {pct:0,label:'Cancelado',state:'canc'};
  if(real) return {pct:100,label:'Entregado',state:'done'};
  if(!emb) return {pct:5,label:'En preparación',state:'prep'};
  if(!est) return {pct:50,label:'En tránsito',state:'transit'};
  const total=daysBetween(emb,est),elapsed=daysBetween(emb,today);
  let pct = total<=0 ? (elapsed>=0?100:50) : Math.max(0,Math.min(100,Math.round(elapsed/total*100)));
  if(elapsed<0) return {pct:5,label:'Por embarcar',state:'prep'};
  if(pct>=100) return {pct:100,label:'Llegada estimada hoy/vencida',state:'late'};
  return {pct,label:'En tránsito',state:'transit'};
}
function onTime(g){const est=parseD(g.eest),real=parseD(g.ereal);if(!est||!real)return null;return daysBetween(real,est)>=0;}

let SESSION=null;

function renderLogin(){
  const root=$('#view');root.innerHTML='';
  const card=el('div','card login');
  const lhead=el('div','loginhead');
  lhead.innerHTML='<h2>Consulta tus envíos</h2><span class="loginlogo"><img src="'+D.logo+'" alt="PadColor"></span>';
  card.appendChild(lhead);
  card.appendChild(el('p','muted','Selecciona cómo deseas ingresar.'));
  const tabs=el('div','tabs');
  const tCli=el('button','tab active','Soy Cliente'),tAg=el('button','tab','Soy Agente');
  tabs.append(tCli,tAg);card.appendChild(tabs);
  const cliBox=el('div','tabpane');
  cliBox.innerHTML='<label>Razón social / Nombre</label>'
    +'<div class="ac"><input id="cliName" autocomplete="off" placeholder="Empieza a escribir tu razón social…"><div class="aclist" id="cliAC"></div></div>'
    +'<label>RFC</label><input id="cliRFC" autocomplete="off" placeholder="Tu RFC (debe coincidir)">'
    +'<button class="btn primary" id="cliGo">Ver mis guías</button><div class="err" id="cliErr"></div>';
  const agBox=el('div','tabpane hidden');
  agBox.innerHTML='<label>Nombre del agente</label>'
    +'<div class="ac"><input id="agName" autocomplete="off" placeholder="Empieza a escribir tu nombre…"><div class="aclist" id="agAC"></div></div>'
    +'<label>Número de agente <span class="hint">(escríbelo de memoria, ej. VTA20)</span></label>'
    +'<input id="agCode" autocomplete="off" placeholder="Tu clave VTA">'
    +'<button class="btn primary" id="agGo">Ver mis clientes</button><div class="err" id="agErr"></div>';
  card.append(cliBox,agBox);root.appendChild(card);
  tCli.onclick=()=>{tCli.classList.add('active');tAg.classList.remove('active');cliBox.classList.remove('hidden');agBox.classList.add('hidden');};
  tAg.onclick=()=>{tAg.classList.add('active');tCli.classList.remove('active');agBox.classList.remove('hidden');cliBox.classList.add('hidden');};

  const cliItems=Object.values(D.clientes).map(c=>({label:c.cliente,rfc:c.rfc}));
  setupAC($('#cliName'),$('#cliAC'),cliItems,it=>{$('#cliName').value=it.label;});
  const agItems=Object.values(D.agentes).map(a=>({label:a.nombre}));
  setupAC($('#agName'),$('#agAC'),agItems,it=>{$('#agName').value=it.label;});

  $('#cliGo').onclick=()=>{
    const name=$('#cliName').value.trim().toUpperCase(),rfc=$('#cliRFC').value.trim().toUpperCase();
    const m=Object.values(D.clientes).find(c=>c.cliente.toUpperCase()===name&&c.rfc.toUpperCase()===rfc);
    if(!m){$('#cliErr').textContent='La razón social y el RFC no coinciden. Verifica tus datos.';return;}
    SESSION={mode:'cliente',clienteKey:m.rfc+'|'+m.cliente,cliente:m.cliente,agente:m.agente};renderDashboard();
  };
  $('#agGo').onclick=()=>{
    const name=$('#agName').value.trim(),code=$('#agCode').value.trim().toUpperCase();
    const a=Object.values(D.agentes).find(x=>x.nombre.toLowerCase()===name.toLowerCase());
    if(!a){$('#agErr').textContent='Nombre de agente no encontrado.';return;}
    if(!a.vtas.includes(code)){$('#agErr').textContent='El número de agente no corresponde a ese nombre.';return;}
    SESSION={mode:'agente',agente:a.nombre,vtas:a.vtas};renderDashboard();
  };
}
function setupAC(input,list,items,onPick){
  const close=()=>{list.innerHTML='';list.classList.remove('open');};
  input.addEventListener('input',()=>{
    const q=input.value.trim().toLowerCase();list.innerHTML='';
    if(!q){close();return;}
    const hits=items.filter(it=>it.label.toLowerCase().includes(q)).slice(0,8);
    if(!hits.length){close();return;}
    hits.forEach(it=>{const r=el('div','acitem',it.label+(it.rfc?' <span class="acrfc">'+it.rfc+'</span>':''));r.onclick=()=>{onPick(it);close();};list.appendChild(r);});
    list.classList.add('open');
  });
  input.addEventListener('blur',()=>setTimeout(close,180));
}

let CURRENT=[];
function scopeGuides(){
  return SESSION.mode==='cliente'
    ? D.guias.filter(g=>g.ck===SESSION.clienteKey)
    : D.guias.filter(g=>g.agente===SESSION.agente);
}

let TAB='guias';
function renderDashboard(){
  CURRENT=scopeGuides();
  const root=$('#view');root.innerHTML='';
  const bar=el('div','sessionbar');
  if(SESSION.mode==='cliente'){
    const a=D.agentes[SESSION.agente]||{};
    let contacto='';
    if(a.nombre){
      contacto='<div class="agentbox"><span class="agentlbl">Tu agente</span><strong>'+a.nombre+'</strong>'
        +(a.correo?' · <a href="mailto:'+a.correo+'">'+a.correo+'</a>':'')
        +(a.tel?' · <a href="tel:'+a.tel+'">'+a.tel+'</a>':'')
        +(!a.correo&&!a.tel?' <span class="muted">(contacto no disponible)</span>':'')+'</div>';
    }
    bar.innerHTML='<div><span class="role">Cliente</span> <strong>'+SESSION.cliente+'</strong>'+contacto+'</div>';
  } else {
    bar.innerHTML='<div><span class="role">Agente</span> <strong>'+SESSION.agente+'</strong> <span class="muted">('+SESSION.vtas.join(', ')+')</span></div>';
  }
  const out=el('button','btn ghost small','Salir');out.onclick=()=>{SESSION=null;TAB='guias';renderLogin();};
  bar.appendChild(out);root.appendChild(bar);

  const total=CURRENT.length,entregadas=CURRENT.filter(g=>g.ereal).length;
  const transito=CURRENT.filter(g=>{const p=progress(g);return p.state==='transit'||p.state==='late';}).length;
  const nfact=CURRENT.reduce((a,g)=>a+g.nfact,0);
  const kpi=el('div','kpis');
  kpi.innerHTML=kpiCard('Guías',total,'var(--blue)')+kpiCard('En tránsito',transito,'var(--magenta)')
    +kpiCard('Entregadas',entregadas,'var(--ok)')+kpiCard('Facturas',nfact,'#555');
  root.appendChild(kpi);

  const tabs=el('div','viewtabs');
  const mk=(id,lbl)=>{const b=el('button','vtab'+(TAB===id?' active':''),lbl);b.onclick=()=>{TAB=id;renderDashboard();};return b;};
  tabs.append(mk('guias','📦 Guías'),mk('report','📊 Reporte por transportista'));
  root.appendChild(tabs);

  if(TAB==='guias') renderGuiasTab(root); else renderReportTab(root);
}
function kpiCard(l,v,c){return '<div class="kpi"><div class="kpival" style="color:'+c+'">'+v+'</div><div class="kpilbl">'+l+'</div></div>';}

function dateInRange(s,from,to){if(!s)return false;if(from&&s<from)return false;if(to&&s>to)return false;return true;}

function renderGuiasTab(root){
  const ctr=el('div','controls');
  ctr.innerHTML='<div class="ac grow"><input id="search" autocomplete="off" placeholder="Buscar por guía, factura, ciudad, transportista…"><div class="aclist" id="searchAC"></div></div>'
    +'<select id="fStatus"><option value="">Todos los estatus</option><option value="transit">En tránsito</option><option value="late">Vencidas / hoy</option><option value="done">Entregadas</option><option value="prep">En preparación</option><option value="canc">Canceladas</option></select>'
    +(SESSION.mode==='agente'?'<select id="fCliente"><option value="">Todos los clientes</option></select>':'')
    +'<button class="btn primary small" id="dl">⬇ Excel</button>';
  root.appendChild(ctr);
  const dr=el('div','daterow');
  dr.innerHTML='<span class="drlbl">Rango por:</span>'
    +'<select id="dField"><option value="fpedido">Fecha de pedido</option><option value="fembarque">Fecha de envío</option></select>'
    +'<label class="drmini">Desde <input type="date" id="dFrom"></label>'
    +'<label class="drmini">Hasta <input type="date" id="dTo"></label>'
    +'<button class="btn ghost small" id="dClear">Limpiar</button>';
  root.appendChild(dr);
  if(SESSION.mode==='agente'){const sel=$('#fCliente');[...new Set(CURRENT.map(g=>g.cliente))].sort().forEach(c=>{const o=el('option',null,c);o.value=c;sel.appendChild(o);});sel.onchange=applyGuias;}
  const sugg=[...new Set(CURRENT.flatMap(g=>[g.guia,g.ciudad,g.transportista].concat(g.facturas.map(f=>f.factura))).filter(Boolean))];
  setupAC($('#search'),$('#searchAC'),sugg.map(x=>({label:x})),it=>{$('#search').value=it.label;applyGuias();});
  $('#search').addEventListener('input',applyGuias);
  $('#fStatus').onchange=applyGuias;$('#dField').onchange=applyGuias;
  $('#dFrom').onchange=applyGuias;$('#dTo').onchange=applyGuias;
  $('#dClear').onclick=()=>{$('#dFrom').value='';$('#dTo').value='';applyGuias();};
  $('#dl').onclick=()=>downloadGuias(filteredGuias());
  const wrap=el('div','listwrap');wrap.id='listwrap';root.appendChild(wrap);
  applyGuias();
}
function filteredGuias(){
  const q=($('#search')&&$('#search').value||'').trim().toLowerCase();
  const st=$('#fStatus')&&$('#fStatus').value||'';const cl=$('#fCliente')&&$('#fCliente').value||'';
  const fld=$('#dField')&&$('#dField').value||'fpedido';const from=$('#dFrom')&&$('#dFrom').value||'';const to=$('#dTo')&&$('#dTo').value||'';
  return CURRENT.filter(g=>{
    if(cl&&g.cliente!==cl)return false;
    if(st){const p=progress(g);if(p.state!==st)return false;}
    if(from||to){if(!dateInRange(g[fld],from,to))return false;}
    if(q){const hay=[g.guia,g.ciudad,g.estado,g.transportista,g.cliente].concat(g.facturas.map(f=>f.factura)).join(' ').toLowerCase();if(!hay.includes(q))return false;}
    return true;
  });
}
function applyGuias(){
  const rows=filteredGuias().sort((a,b)=>(b.fembarque||'').localeCompare(a.fembarque||''));
  const wrap=$('#listwrap');wrap.innerHTML='';
  if(!rows.length){wrap.appendChild(el('div','empty','No se encontraron guías con esos criterios.'));return;}
  wrap.appendChild(el('div','rescount',rows.length+' guía(s)'));
  rows.forEach(g=>wrap.appendChild(guideCard(g)));
}
function daysCount(a,b){const da=parseD(a),db=parseD(b);if(!da||!db)return null;return daysBetween(da,db);}
function dcell(n,lbl){return n==null?'<span class="dc dcna">—</span>':'<span class="dc" title="'+lbl+'">'+n+(n===1?' día':' días')+'</span>';}
function transpInfo(t){
  if(/transportista/i.test(t)) return {cls:'tp-ext',label:'Transportista'};
  if(/propio/i.test(t)) return {cls:'tp-own',label:'Propio'};
  return {cls:'tp-na',label:t||'—'};
}
function guideCard(g){
  const p=progress(g);const c=el('div','gcard');
  const guiaLabel=g.guia.indexOf('(SIN GUÍA)')===0?'<span class="muted">'+g.guia+'</span>':g.guia;
  const tp=transpInfo(g.transporte);
  const prep=daysCount(g.fpedido,g.fembarque);          // pedido -> embarque
  const plan=daysCount(g.fembarque,g.eest);             // embarque -> estimada
  const realDays=g.ereal?daysCount(g.fembarque,g.ereal):null; // embarque -> real
  // timeline row
  let tl='<div class="timeline">'
    +'<div class="tlstep"><span class="mlbl">Pedido</span><span class="tldate">'+fmtDate(g.fpedido)+'</span></div>'
    +'<div class="tlarrow">'+dcell(prep,'Días de preparación (pedido → embarque)')+'</div>'
    +'<div class="tlstep"><span class="mlbl">Embarque</span><span class="tldate">'+fmtDate(g.fembarque)+'</span></div>'
    +'<div class="tlarrow">'+dcell(plan,'Días de tránsito planeado (embarque → estimada)')+'</div>'
    +'<div class="tlstep"><span class="mlbl">Entrega estimada</span><span class="tldate">'+fmtDate(g.eest)+'</span></div>';
  if(g.ereal){
    tl+='<div class="tlarrow">'+dcell(realDays,'Días de tránsito real (embarque → entrega real)')+'</div>'
      +'<div class="tlstep tlreal"><span class="mlbl">Entrega real</span><span class="tldate">'+fmtDate(g.ereal)+'</span></div>';
  }
  tl+='</div>';

  c.innerHTML='<div class="ghead"><div><div class="gtitle">📦 Guía '+guiaLabel+'</div>'
    +'<div class="gsub">'+(g.transportista||'—')+' · '+g.ciudad+', '+g.estado+'</div></div>'
    +'<div class="headtags">'
    +'<div class="tagcol"><span class="taglbl">Cliente</span><span class="clbadge">'+g.cliente+'</span></div>'
    +'<div class="tagcol"><span class="taglbl">Estatus</span><span class="badge '+p.state+'">'+p.label+'</span></div>'
    +'<div class="tagcol"><span class="taglbl">Tipo de Transporte</span><span class="tpbadge '+tp.cls+'">'+tp.label+'</span></div>'
    +'</div></div>'
    +'<div class="prog"><div class="progbar"><div class="progfill '+p.state+'" style="width:'+p.pct+'%"></div></div>'
    +'<div class="proginfo"><span>Embarque: '+fmtDate(g.fembarque)+'</span><span>'+p.pct+'%</span><span>'+fmtDate(g.eest)+'</span></div></div>'
    +tl
    +'<button class="btn ghost small toggle">Ver facturas ('+g.nfact+') ▾</button><div class="facts hidden"></div>';
  const fbox=c.querySelector('.facts');
  fbox.appendChild(el('div','fact facthead','<span class="fno">Factura</span><span>Fecha</span><span class="ftag">Temporada</span>'));
  g.facturas.forEach(f=>fbox.appendChild(el('div','fact','<span class="fno">'+f.factura+'</span><span>'+fmtDate(f.ffactura)+'</span><span class="ftag">'+(f.temporada||'')+'</span>')));
  c.querySelector('.toggle').onclick=function(){fbox.classList.toggle('hidden');this.textContent=fbox.classList.contains('hidden')?'Ver facturas ('+g.nfact+') ▾':'Ocultar facturas ▴';};
  return c;
}

function carrierStats(scope){
  const m={};
  scope.forEach(g=>{
    const t=g.transportista||'(sin transportista)';
    const s=m[t]||(m[t]={t:t,guias:0,facturas:0,entregadas:0,ontime:0,evaluables:0,diasSum:0,diasN:0,flete:0});
    s.guias++;s.facturas+=g.nfact;s.flete+=g.flete;
    if(g.ereal)s.entregadas++;
    const ot=onTime(g);
    if(ot!==null){s.evaluables++;if(ot)s.ontime++;
      if(g.fembarque){s.diasSum+=daysBetween(parseD(g.fembarque),parseD(g.ereal));s.diasN++;}}
  });
  return Object.values(m).map(s=>{
    let score=null;
    if(s.evaluables>0) score=Math.round(s.ontime/s.evaluables*100)/10;
    return Object.assign(s,{score:score,pctEntrega:s.guias?Math.round(s.entregadas/s.guias*100):0,
      promDias:s.diasN?Math.round(s.diasSum/s.diasN*10)/10:null});
  }).sort((a,b)=>(b.score==null?-1:b.score)-(a.score==null?-1:a.score)||b.guias-a.guias);
}
function renderReportTab(root){
  const ctr=el('div','controls');
  ctr.innerHTML='<div class="ac grow"><input id="rSearch" autocomplete="off" placeholder="Filtrar transportista…"></div>'
    +'<span class="drlbl">Rango por:</span>'
    +'<select id="rField"><option value="fpedido">Fecha de pedido</option><option value="fembarque">Fecha de envío</option></select>'
    +'<label class="drmini">Desde <input type="date" id="rFrom"></label>'
    +'<label class="drmini">Hasta <input type="date" id="rTo"></label>'
    +'<button class="btn ghost small" id="rClear">Limpiar</button>'
    +'<button class="btn primary small" id="rDl">⬇ Excel</button>';
  root.appendChild(ctr);
  root.appendChild(el('div','rnote','Calificación 0–10 = cumplimiento de la fecha estimada de entrega (proporción de guías entregadas a tiempo, sobre las que ya tienen entrega registrada).'));
  const wrap=el('div','listwrap');wrap.id='repwrap';root.appendChild(wrap);
  const compute=()=>{
    const q=($('#rSearch').value||'').trim().toLowerCase();
    const fld=$('#rField').value,from=$('#rFrom').value,to=$('#rTo').value;
    let scope=CURRENT;if(from||to)scope=scope.filter(g=>dateInRange(g[fld],from,to));
    let stats=carrierStats(scope);if(q)stats=stats.filter(s=>s.t.toLowerCase().includes(q));
    return stats;
  };
  const refresh=()=>drawReport(compute());
  $('#rSearch').addEventListener('input',refresh);
  ['rField','rFrom','rTo'].forEach(id=>$('#'+id).onchange=refresh);
  $('#rClear').onclick=()=>{$('#rFrom').value='';$('#rTo').value='';$('#rSearch').value='';refresh();};
  $('#rDl').onclick=()=>downloadReport(compute());
  refresh();
}
function scoreColor(s){if(s===null)return '#999';if(s>=8)return 'var(--ok)';if(s>=6)return 'var(--warn)';return 'var(--late)';}
function drawReport(stats){
  const wrap=$('#repwrap');wrap.innerHTML='';
  if(!stats.length){wrap.appendChild(el('div','empty','Sin datos de transportistas en este rango.'));return;}
  wrap.appendChild(el('div','rescount',stats.length+' transportista(s)'));
  stats.forEach(s=>{
    const card=el('div','rcard');
    const sc=s.score===null?'N/D':s.score.toFixed(1);
    card.innerHTML='<div class="rhead"><div class="rname">🚚 '+s.t+'</div>'
      +'<div class="rscore" style="color:'+scoreColor(s.score)+'">'+sc+'<span class="rscoremax">/10</span></div></div>'
      +'<div class="rbarwrap"><div class="rbar" style="width:'+(s.score===null?0:s.score*10)+'%;background:'+scoreColor(s.score)+'"></div></div>'
      +'<div class="rmeta"><div><span class="mlbl">Guías</span>'+s.guias+'</div>'
      +'<div><span class="mlbl">Facturas</span>'+s.facturas+'</div>'
      +'<div><span class="mlbl">Entregadas</span>'+s.entregadas+' ('+s.pctEntrega+'%)</div>'
      +'<div><span class="mlbl">A tiempo</span>'+(s.evaluables?s.ontime+'/'+s.evaluables:'—')+'</div>'
      +'<div><span class="mlbl">Días prom. tránsito</span>'+(s.promDias==null?'—':s.promDias)+'</div></div>';
    wrap.appendChild(card);
  });
}

function styleHeader(ws){const r=XLSX.utils.decode_range(ws['!ref']);for(let C=r.s.c;C<=r.e.c;C++){const c=ws[XLSX.utils.encode_cell({r:0,c:C})];if(c)c.s={font:{bold:true,color:{rgb:'FFFFFF'}},fill:{fgColor:{rgb:'001AA5'}},alignment:{horizontal:'center'}};}}
function downloadGuias(rows){
  const showF=SESSION.mode==='agente';
  const head=['Guía','Cliente','Ciudad','Estado','Transportista','Estatus','Fecha pedido','Fecha envío','Entrega estimada','Entrega real','% Avance','Facturas'].concat(showF?['RFC','Costo flete']:[]);
  const aoa=[head];
  rows.forEach(g=>{const p=progress(g);const r=[g.guia,g.cliente,g.ciudad,g.estado,g.transportista,p.label,g.fpedido,g.fembarque,g.eest,g.ereal||'',p.pct,g.facturas.map(f=>f.factura).join(', ')];if(showF)r.push(g.rfc,g.flete);aoa.push(r);});
  const ws=XLSX.utils.aoa_to_sheet(aoa);ws['!cols']=head.map((h,i)=>({wch:i===1?30:i===11?28:14}));styleHeader(ws);
  const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Guías');
  XLSX.writeFile(wb,'PadColor_guias_'+D.generado+'.xlsx');
}
function downloadReport(stats){
  const head=['Transportista','Calificación (0-10)','Guías','Facturas','Entregadas','% Entrega','A tiempo','Evaluables','Días prom. tránsito'];
  const aoa=[head];
  stats.forEach(s=>aoa.push([s.t,s.score===null?'N/D':s.score,s.guias,s.facturas,s.entregadas,s.pctEntrega,s.ontime,s.evaluables,s.promDias==null?'':s.promDias]));
  const ws=XLSX.utils.aoa_to_sheet(aoa);ws['!cols']=head.map((h,i)=>({wch:i===0?28:14}));styleHeader(ws);
  const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Transportistas');
  XLSX.writeFile(wb,'PadColor_reporte_transportistas_'+D.generado+'.xlsx');
}

renderLogin();
})();
</script>
</body></html>